export function LogoMondelezAssinatura({
  cor = "roxo",
  className,
}: {
  readonly cor?: "roxo" | "branco";
  readonly className?: string;
}) {
  return (
    <svg
      viewBox="154 231 1732 653"
      data-slot="logo-mondelez"
      role="img"
      aria-label="Mondelēz International. Snacking Made Right"
      className={cn("h-auto shrink-0", className)}
      style={{ minWidth: LARGURA_MINIMA_ASSINATURA }}
      fill={cor === "roxo" ? "#4f2170" : "#ffffff"}
    >
      <title>Mondelēz International. Snacking Made Right</title>
      {TRACADOS.map(([m, d], i) => (
        // A lista é fixa: a posição completa a chave quando duas matrizes se repetem.
        <path key={`${i}-${m}`} transform={`matrix(${m})`} d={d} />
      ))}
    </svg>
  );
}
